SELECT t_price_bidding.tender_number AS tenderNumber, t_price_bidding.customer AS customer, t_price_bidding.latest_quotation AS latestQuotation, t_price_bidding.quantity AS quantity, t_price_bidding.quotation_time AS quotationTime, COUNT(t_price_bidding.latest_quotation) AS biddingFrequency, t_sales_bidding.low_price AS initialQuotation FROM t_price_bidding LEFT JOIN t_sales_bidding ON t_price_bidding.tender_number = t_sales_bidding.tender_number WHERE t_price_bidding.is_deleted = '0' AND t_price_bidding.tender_number =#{tenderNumber}
AND t_price_bidding.customer_id LIKE CONCAT('%', #{customerId}, '%')
GROUP BY t_price_bidding.tender_number, t_price_bidding.customer, t_price_bidding.latest_quotation, t_price_bidding.quantity, t_price_bidding.quotation_time, t_sales_bidding.low_price ORDER BY t_price_bidding.quotation_time DESC

SELECT t_delivery_place.delivery_place_name AS deliveryPlaceName
FROM t_delivery_place
WHERE t_delivery_place.delivery_place_no = #{deliveryPlaceNo}

SELECT t_depot.depot_name AS depotName
FROM t_depot
WHERE t_depot.depot_no = #{depotNo}
